// Small helper so each record stays on ~10 readable lines instead of 25+
// kind: "drug-drug" (default) | "drug-disease" | "drug-food" | "drug-drink" | "drug-lab"
// source: "curated" (default, from the project document) | "ai-supplemented" (added by Claude, pending pharmacist review)
function mk(id, drugA, drugB, type, severity, contraindicated, direction, risk, mechanism, effect, monitoring, action, evidence, note, kind, source) {
  return { id, drugA, drugB, type, severity, contraindicated, direction, risk, mechanism, effect, monitoring, action, evidence, note: note || null, kind: kind || "drug-drug", source: source || "curated" };
}

