// Drugs that should be treated as members of a shared interaction class
// (i.e. they don't have their own record, they inherit the class record).
// Reserved for future drug-class groupings (none needed currently — every
// drug, including each individual fluoroquinolone, now has its own record).
const CLASS_ALIASES = {};

// Build a full index of every searchable "item" (medicine, condition, food,
// drink or lab test) with what KIND it is, so the frontend can tag chips
// correctly (e.g. "Asthma" shows as a condition, not a medicine).
const KIND_KEYWORDS = {
  "drug-drug": "medicine",
  "drug-disease": "condition",
  "drug-food": "food",
  "drug-drink": "drink",
  "drug-lab": "lab test",
};

function buildItemIndex() {
  const index = {}; // name -> kind label
  INTERACTIONS.forEach(i => {
    if (!(i.drugA in index)) index[i.drugA] = "medicine"; // drugA is always the actual drug
    const bKind = KIND_KEYWORDS[i.kind] || "medicine";
    if (!(i.drugB in index)) index[i.drugB] = bKind;
  });
  return index;
}

const ITEM_KINDS = buildItemIndex();
const DRUG_LIST = Object.keys(ITEM_KINDS).sort((a, b) => a.localeCompare(b));

// Node/Express reads this same file directly — one dataset, no duplication.
if (typeof module !== "undefined" && module.exports) {
  module.exports = { INTERACTIONS, DRUG_LIST, CLASS_ALIASES, ITEM_KINDS };
}
